export const examples = Object.entries(groups).flatMap(([category, texts]) => texts.map((body, index) => ({
  id: `${category}-${index + 1}`,
  category,
  label: positive.has(category) ? 1 : 0,
  kind: "comment",
  title: "",
  body
})));

